describe('Internet Connection Drop Message', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display friendly error message when internet connection drops', () => {
    // Setup: simulate initial page load with internet connection
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify page loads successfully
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    // Simulate internet connection drop
    cy.intercept('GET', '/api/data', {
      statusCode: 503,
      body: { error: 'Service Unavailable' }
    }).as('connectionError');
    cy.wait('@connectionError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unable to load data');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify retry button has correct text
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');

    // Verify error message has a friendly tone
    cy.get('[data-testid="error-message"]').should('have.css', 'color', 'rgb(102, 178, 255)');

    // Verify error message has a timeout countdown
    cy.get('[data-testid="error-message"]').should('contain', 'Please try again in 30 seconds');

    // Verify connection status icon is visible
    cy.get('[data-testid="connection-status-icon"]').should('be.visible');

    // Verify connection status icon shows 'no connection'
    cy.get('[data-testid="connection-status-icon"]').should('have.class', 'no-connection');

    // Verify error message disappears after 30 seconds
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify page is still functional after error
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });

